__NUXT_JSONP__("/tr", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002F52.198.144.187:81",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"Insanlarin MLI'ı (Mentor Dil Enstitüsü) Seçmeleri'nin 3 Nedeni",lists:[{image:"\u002Fimages\u002Fhome\u002Ftr\u002Fpeople-choose-mli-1.png",title:"Hollywood & Westwood",description:"Los Angeles’ın büyük ve popüler bölgelerinde bulunuyoruz. Öğrenciler sadece İngilizce öğrenmekle kalmayıp aynı zamanda Los Angeles'ın da tadını çıkarabilirler.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Ftr\u002Fpeople-choose-mli-2.png",title:"Sabah, Öğleden sonra ve Akşam sınıfları",description:"Esnek programlara ihtiyaç duyan insanlar için Sabah, Öğleden sonra ve Akşam dersleri sunuyoruz.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Ftr\u002Fpeople-choose-mli-3.png",title:"1 hafta \u002F $201 ～",description:"Harika lokasyon ve Uygun Fiyat! Lütfen fiyatları diğer okullarla karşılaştırın. Ögrenim ucreti bilgilerini istiyorsanız, aşağıda bulunan Bize Ulaşın'a tıklayın.",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Ftr\u002Fmli-highly-rated.png",courses:{title:"Dersler",lists:[{image:d,title:"ESL Programi",subtitle:["Bu program dinleme \u002F konuşma, okuma \u002F kelime hazinesi ve dilbilgisi \u002F yazma derslerinden oluşmaktadır. ESL programı, genel İngilizce becerilerini geliştirmek isteyen öğrenciler için idealdir."]},{image:e,title:"TOEFL® Programi",subtitle:["MLI’ın TOEFL® programı, İnternet Tabanlı Testin (iBT) dört bölümünde başarılı bir skor elde etmek için gerekli beceri ve stratejilerine yoğun bir bakış niteliğindedir."]},{image:d,title:"Vacation ESL programı (kısa dönemli bir öğrenci için)",subtitle:["Bu program dinleme\u002Fkonuşma, okuma\u002Fkelime bilgisi ve gramer\u002Fyazma derslerinden oluşmaktadır. \u003Cbr\u003EKısa süreli İngilizce eğitimi almak isteyen öğrenciler için Tatil ESL programını sunuyoruz."]},{image:e,title:"IELTS™ Programi",subtitle:["IELTS ™, öğrencilerin İngilizce yeterliliklerini değerlendirmek için İngiltere ve Avustralya'da geliştirilmiş bir testtir. Son zamanlarda, birçok Amerikan üniversitesi bir TOEFL® puanı veya IELTS ™ skoru gerektirir. Program dört bölümden oluşmaktadır: dinleme, konuşma, okuma ve yazma. Bu sınıfta, her bölümde yüksek puanlar elde etmek için beceri \u002F stratejileri öğreneceksiniz. IELTS ™ 'nin TOEFL®' den nispeten daha kolay olduğu söylenir. TOEFL®'i bulan öğrenciler için mükemmel bir programdır."]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"Konuşma Programı",subtitle:["Programımız, ilgi çekici etkinlikler ve etkileşimli öğrenme yoluyla İngilizce konuşma becerilerinizi geliştirmeye odaklanmaktadır! Konuşma derslerimizde, öğrenciler geniş bir kelime dağarcığı, deyim ve tabirler keşfedecekler ve konuşmalarını canlandıracaklar. CMAR sınıfımızda telaffuzunuzu prati̇k edebilirsiniz. Eğlenceli tartışmalar, rol oyunları ve grup etkinlikleri aracılığıyla kendinizi ifade etme ve anlamlı diyaloglara katılma konusunda özgüven kazanacaksınız. Tecrübeli eğitmenlerimiz, sizi destekleyici bir öğrenme ortamında yönlendirerek dil keşfi yolculuğunda sizinle birlikte olacaklardır."]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"İş ile birlikde TOEIC® Programı",subtitle:["TOEIC® testi, iş dünyasında İngilizce yeterliliğinin bir göstergesidir ve dünya çapında çeşitli şirketler ve kuruluşlar tarafından kullanılmaktadır. Standart İş programına ek olarak, TOEIC® programı öğrencileri, temel kelime dağarcığını tanıtarak ve testte yüksek bir skor elde etmek için stratejileri keşfederek TOEIC® - Dinleme ve Okuma Sınavı'nda başarıya hazırlar. Bu program, kelime bilgisi, okuma, dinleme ve dilbilgisi gibi İngilizce becerilerinizi geliştirmede yardımcı olacaktır. Doğru cevapları bulma stratejilerini öğrenerek yüksek bir skor elde edebileceksiniz."]}]},schedule:"\u002Fimages\u002Fhome\u002Fen\u002Ffree_trial_banner-En.png",link:"\u002Ftr\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"Yer \u002F Kampüs",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"Westwood Kampüsü",subtitle:"Westwood, Los Angeles’ın batı tarafında yer alan canlı ve eşsiz bir semttir. Westwood UCLA'nın evi olmakla ünlüdür. Çok sayıda üniversite öğrencisi ve çok sayıda mağaza, restoran ve takılmak için güvenli yerler olduğu için öğrenciler için çok eğlenceli ve popüler bir alandır.",read_more:["\u003Ca href=\"\u002Ftr\u002Fwestwood\u002F\"\u003E» DAHA FAZLA OKU\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"Hollywood Kampüsü",subtitle:"Hollywood kampüsü, ünlü Çin Tiyatrosu'nun hemen yanındadır. Hollywood bölgesinde ünlü sinema salonları, iyi restoranlar, mağazalar ve kulüpler bulunmaktadır. Bu alan her zaman çok canlı.",read_more:["\u003Ca href=\"\u002Ftr\u002Fhollywood\u002F\"\u003E» DAHA FAZLA OKU\u003C\u002Fa\u003E"]}]},testimonials:{title:"Öğrenci tanıklıkları",seemoreBtn:"Daha fazla görüntüle",TestimonialLink:"\u002Ftr\u002Ftestimonials",readmoreBtn:"Daha fazla oku"},dir:"\u002Fhome",path:"\u002Fhome\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:29.619Z",updatedAt:"2025-05-26T12:06:27.786Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Ftr\u002Ffeature\u002F\"\u003E» DAHA FAZLA OKU\u003C\u002Fa\u003E","tr","Los Angeles'da Uygun İngilizce Okullari | Mentor Dil Enstitüsü","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));